            var B = ColVec2(0, 1);
            var Q = Eye(2); var R = R1(1);
            var uLo = Vec1((double)(-1e30)); var uHi = Vec1((double)1e30);   // library's own "unbounded" sentinel (QP.solve's own INF convention)

            var K = new doubleMxN(1, 2, Allocator.Temp);
            var lqrInfo = Control.lqr(in A, in B, in Q, in R, ref K);
            AssertTrue(lqrInfo.status == LQRStatus.Converged);

            var mpc = new doubleMPCState(2, 1, 8, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);
            var reference = new doubleN(2, Allocator.Temp);   // zero-initialized: track to the origin
            var u0 = new doubleN(1, Allocator.Temp, true);
            var rng = new Unity.Mathematics.Random(0xA53Cu);

            for (int trial = 0; trial < 10; trial++)
            {
                var x0 = new doubleN(2, Allocator.Temp, true);
                x0[0] = (double)rng.NextFloat(-2f, 2f);
                x0[1] = (double)rng.NextFloat(-2f, 2f);

                var info = MPC.solve(ref mpc, in x0, in reference, ref u0);
                AssertTrue(info.status == MPCStatus.Optimal || info.status == MPCStatus.MaxIterations);

                double u0lqr = -(K[0, 0] * x0[0] + K[0, 1] * x0[1]);
