        // ============================ (d) warm-start health ============================

        // Receding-horizon run from a displaced start (x0=(5,0), tight input bounds [-0.5,0.5], N=8):
        // active-set churn must collapse to a small bound after a short initial transient.
        void WarmStartChurnBound()
        {
            var A = Mat2(1, 1, 0, 1); var B = ColVec2(0, 1); var Q = Eye(2); var R = R1(1);
            var uLo = Vec1((double)(-0.5)); var uHi = Vec1((double)0.5);
            var mpc = new doubleMPCState(2, 1, 8, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);

            var x = Vec2(5, 0);
            var reference = new doubleN(2, Allocator.Temp);   // zero-initialized: track to the origin
            var u0 = new doubleN(1, Allocator.Temp, true);

            const int steadyFrame = 8;
            const int totalFrames = 20;
            for (int f = 0; f < totalFrames; f++)
            {
                var info = MPC.solve(ref mpc, in x, in reference, ref u0);
                AssertTrue(info.status == MPCStatus.Optimal || info.status == MPCStatus.MaxIterations);
                if (f >= steadyFrame) AssertLE(info.activeSetChanges, 3);

                double x0n = x[0] + x[1];
                double x1n = x[1] + u0[0];
                x[0] = x0n; x[1] = x1n;
            }

            x.Dispose(); reference.Dispose(); u0.Dispose(); mpc.Dispose();
            A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
        }

        // At a fixed later frame, a warm-started sequence's own iteration count must not exceed a
        // freshly-constructed (cold) state solving the IDENTICAL point (same optimum either way -- a
        // strictly convex QP's solution does not depend on warm-starting, only the pivot count does).
        void WarmIterationsBeatCold()
        {
            var A = Mat2(1, 1, 0, 1); var B = ColVec2(0, 1); var Q = Eye(2); var R = R1(1);
            var uLo = Vec1((double)(-0.5)); var uHi = Vec1((double)0.5);
            var mpcWarm = new doubleMPCState(2, 1, 8, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);

            var x = Vec2(5, 0);
            var reference = new doubleN(2, Allocator.Temp);   // zero-initialized: track to the origin
            var u0 = new doubleN(1, Allocator.Temp, true);

            const int targetFrame = 10;
            var xAtTarget = new doubleN(2, Allocator.Temp, true);
            int warmIters = 0;
            for (int f = 0; f <= targetFrame; f++)
            {
                if (f == targetFrame) xAtTarget.CopyFrom(x);
                var info = MPC.solve(ref mpcWarm, in x, in reference, ref u0);
                if (f == targetFrame) warmIters = info.iterations;

                double x0n = x[0] + x[1];
                double x1n = x[1] + u0[0];
                x[0] = x0n; x[1] = x1n;
            }

            var mpcCold = new doubleMPCState(2, 1, 8, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);
            var u0c = new doubleN(1, Allocator.Temp, true);
            var coldInfo = MPC.solve(ref mpcCold, in xAtTarget, in reference, ref u0c);
            AssertTrue(coldInfo.status == MPCStatus.Optimal || coldInfo.status == MPCStatus.MaxIterations);

            AssertLE(warmIters, coldInfo.iterations);

            u0c.Dispose(); mpcCold.Dispose(); xAtTarget.Dispose();
            x.Dispose(); reference.Dispose(); u0.Dispose(); mpcWarm.Dispose();
            A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
        }

        // ============================ (e) prestabilization correctness ============================

        // Regression test for a post-ship audit finding (2026-07-12, OP/DEVLOG.md): the prestabilized
        // input-bound rows used the WRONG Phi/Gamma block (x_{k+1}'s coefficients instead of x_k's), and
        // a second, related defect applied R naively to v instead of correctly expanding u_k^T R u_k
        // under u_k = -Kstab x_k + v_k. Both are fixed the same way: prestabilization is a PURE change
        // of coordinates, so it must reproduce the IDENTICAL physical answer as solving the SAME
        // (A,B,Q,R,uLo,uHi) problem without it -- x0=(3,1.9) is the SAME binding scenario as
        // SaturatedMatchesOracle (u0 saturates at uLo=-2), reused here as the discriminating case: the
        // ORIGINAL (buggy) row assembly returned u0 far outside [-2,2] on this exact scenario (verified
        // in the design's numpy prototype before this fix), so both assertions below would have failed
        // it.
        void PrestabBindingBoundMatchesNonPrestab()
        {
            var A = Mat2(1, 1, 0, 1); var B = ColVec2(0, 1); var Q = Eye(2); var R = R1(1);
            var uLo = Vec1((double)(-2)); var uHi = Vec1((double)2);

            var Kstab = new doubleMxN(1, 2, Allocator.Temp);
            var lqrInfo = Control.lqr(in A, in B, in Q, in R, ref Kstab);
            AssertTrue(lqrInfo.status == LQRStatus.Converged);

            var mpcPlain = new doubleMPCState(2, 1, 8, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);
            var mpcPrestab = new doubleMPCState(2, 1, 8, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi,
                                                default, default, default, default(doubleN), (double)0, (double)0, in Kstab);

            var x0 = Vec2(3, (double)1.9);
            var reference = new doubleN(2, Allocator.Temp);   // zero-initialized: track to the origin
            var u0Plain = new doubleN(1, Allocator.Temp, true);
            var u0Prestab = new doubleN(1, Allocator.Temp, true);

            var infoPlain = MPC.solve(ref mpcPlain, in x0, in reference, ref u0Plain);
            var infoPrestab = MPC.solve(ref mpcPrestab, in x0, in reference, ref u0Prestab);
            AssertTrue(infoPlain.status == MPCStatus.Optimal || infoPlain.status == MPCStatus.MaxIterations);
            AssertTrue(infoPrestab.status == MPCStatus.Optimal || infoPrestab.status == MPCStatus.MaxIterations);

            // (i) reconstruct u0 = -Kstab*x0 + v0 INDEPENDENTLY (reading mpcPrestab.Kstab/z directly,
            // not trusting MPC.solve's own internal ExtractU0 conversion) and check it respects the
            // physical input bound -- the off-by-one bug placed this wildly outside [-2,2].
            double uRecon = -(mpcPrestab.Kstab[0, 0] * x0[0] + mpcPrestab.Kstab[0, 1] * x0[1]) + mpcPrestab.z[0];
            AssertClose(uRecon, u0Prestab[0], OracleU0Tol());
            AssertTrue(uRecon >= uLo[0] - OracleU0Tol() && uRecon <= uHi[0] + OracleU0Tol());

            // (ii) same physical problem, different coordinates -- must agree to tight tolerance.
            AssertClose(u0Prestab[0], u0Plain[0], OracleU0Tol());
            AssertClose(u0Prestab[0], (double)(-2.0), OracleU0Tol());   // both saturate at uLo, per the prototype

            x0.Dispose(); reference.Dispose(); u0Plain.Dispose(); u0Prestab.Dispose();
            mpcPlain.Dispose(); mpcPrestab.Dispose(); Kstab.Dispose();
            A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
        }

        // ================================ helpers ================================

        static doubleMxN Mat2(double a, double b, double c, double d)
        {
            var M = new doubleMxN(2, 2, Allocator.Temp);
            M[0, 0] = a; M[0, 1] = b; M[1, 0] = c; M[1, 1] = d;
            return M;
        }

        static doubleMxN ColVec2(double a, double b)
        {
            var M = new doubleMxN(2, 1, Allocator.Temp);
            M[0, 0] = a; M[1, 0] = b;
            return M;
        }

        static doubleMxN Eye(int n)
        {
            var M = new doubleMxN(n, n, Allocator.Temp);
            for (int i = 0; i < n; i++) M[i, i] = (double)1;
            return M;
        }

        static doubleMxN R1(double v)
        {
            var M = new doubleMxN(1, 1, Allocator.Temp);
            M[0, 0] = v;
            return M;
        }

        static doubleMxN WallRow()
        {
            var M = new doubleMxN(1, 2, Allocator.Temp);
            M[0, 0] = (double)1; M[0, 1] = (double)0;
            return M;
        }

        static doubleN Vec1(double v)
        {
            var vec = new doubleN(1, Allocator.Temp, true);
            vec[0] = v;
            return vec;
        }

        static doubleN Vec2(double a, double b)
        {
            var vec = new doubleN(2, Allocator.Temp, true);
            vec[0] = a; vec[1] = b;
            return vec;
        }

        // ---- Fail[0..3] diagnostic asserts (same shape as ControlLQRTests.double.cs) ----
        void AssertTrue(bool cond)
        {
            if (!cond && Fail[0] == (double)0) { Fail[0] = (double)1; Fail[1] = (double)0; Fail[2] = (double)1; Fail[3] = (double)0; }
            Assert.IsTrue(cond);
        }

        void AssertLE(int got, int limit)
        {
            if (!(got <= limit) && Fail[0] == (double)0) { Fail[0] = (double)1; Fail[1] = (double)got; Fail[2] = (double)limit; Fail[3] = (double)(got - limit); }
            Assert.IsTrue(got <= limit);
        }

        void AssertLEd(double got, double limit)
        {
            if (!(got <= limit) && Fail[0] == (double)0) { Fail[0] = (double)1; Fail[1] = (double)got; Fail[2] = (double)limit; Fail[3] = (double)(got - limit); }
            Assert.IsTrue(got <= limit);
        }

        void AssertClose(double a, double b, double precision)
        {
            double diff = math.abs(a - b);
            if (!(diff <= precision) && Fail[0] == (double)0) { Fail[0] = (double)1; Fail[1] = a; Fail[2] = b; Fail[3] = diff; }
            Assert.IsTrue(diff <= precision);
        }

        void AssertCloseD(double a, double b, double precision)
        {
            double diff = math.abs(a - b);
            if (!(diff <= precision) && Fail[0] == (double)0) { Fail[0] = (double)1; Fail[1] = (double)a; Fail[2] = (double)b; Fail[3] = (double)diff; }
            Assert.IsTrue(diff <= precision);
        }
    }

    public static Array GetEnums() => Enum.GetValues(typeof(TestJob.TestType));

    [TestCaseSource("GetEnums")]
    public void MPCTests(TestJob.TestType type)
    {
        var fail = new NativeArray<double>(4, Allocator.TempJob);
        try
        {
            new TestJob() { Type = type, Fail = fail }.Run();
            if (fail[0] != (double)0)
                Assert.Fail($"got {fail[1]}, expected/limit {fail[2]}, diff/extra {fail[3]}");
        }
        catch (Exception e)
        {
            if (fail[0] != (double)0)
                Assert.Fail($"{type}: got {fail[1]}, expected/limit {fail[2]}, diff/extra {fail[3]} ({e.Message})");
            throw;
        }
        finally
        {
            fail.Dispose();
        }
    }

