    [Test]
    public void SolveThrowsOnMismatchedX0()
    {
        var A = new doubleMxN(2, 2, Allocator.Temp); A[0, 0] = 1; A[0, 1] = 1; A[1, 1] = 1;
        var B = new doubleMxN(2, 1, Allocator.Temp); B[1, 0] = 1;
        var Q = new doubleMxN(2, 2, Allocator.Temp); Q[0, 0] = 1; Q[1, 1] = 1;
        var R = new doubleMxN(1, 1, Allocator.Temp); R[0, 0] = 1;
        var uLo = new doubleN(1, Allocator.Temp, true); uLo[0] = (double)(-1);
        var uHi = new doubleN(1, Allocator.Temp, true); uHi[0] = (double)1;
        var mpc = new doubleMPCState(2, 1, 4, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);

        var badX0 = new doubleN(3, Allocator.Temp, true);
        var reference = new doubleN(2, Allocator.Temp);   // zero-initialized: track to the origin
        var u0 = new doubleN(1, Allocator.Temp, true);
        Assert.Catch<ArgumentException>(() => MPC.solve(ref mpc, in badX0, in reference, ref u0));

        badX0.Dispose(); reference.Dispose(); u0.Dispose(); mpc.Dispose();
        A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
    }

    [Test]
    public void SolveThrowsOnBadReferenceLength()
    {
        var A = new doubleMxN(2, 2, Allocator.Temp); A[0, 0] = 1; A[0, 1] = 1; A[1, 1] = 1;
        var B = new doubleMxN(2, 1, Allocator.Temp); B[1, 0] = 1;
        var Q = new doubleMxN(2, 2, Allocator.Temp); Q[0, 0] = 1; Q[1, 1] = 1;
        var R = new doubleMxN(1, 1, Allocator.Temp); R[0, 0] = 1;
        var uLo = new doubleN(1, Allocator.Temp, true); uLo[0] = (double)(-1);
        var uHi = new doubleN(1, Allocator.Temp, true); uHi[0] = (double)1;
        var mpc = new doubleMPCState(2, 1, 4, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);

        var x0 = new doubleN(2, Allocator.Temp, true);
        var badReference = new doubleN(3, Allocator.Temp, true);   // neither n(2) nor N*n(8)
        var u0 = new doubleN(1, Allocator.Temp, true);
        Assert.Catch<ArgumentException>(() => MPC.solve(ref mpc, in x0, in badReference, ref u0));

        x0.Dispose(); badReference.Dispose(); u0.Dispose(); mpc.Dispose();
        A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
    }

    [Test]
    public void ConstructorThrowsOnUnstabilizablePair()
    {
        // A's mode with eigenvalue 2 is uncontrollable (B only actuates the second state), mirroring
        // ControlLQRTests.double.cs's own FailureUnstabilizable job -- the auto-DARE terminal cost
        // cannot be computed, so construction must fail rather than silently produce a bad terminal cost.
        var A = new doubleMxN(2, 2, Allocator.Temp); A[0, 0] = 2; A[1, 1] = (double)0.5;
        var B = new doubleMxN(2, 1, Allocator.Temp); B[1, 0] = 1;
        var Q = new doubleMxN(2, 2, Allocator.Temp); Q[0, 0] = 1; Q[1, 1] = 1;
        var R = new doubleMxN(1, 1, Allocator.Temp); R[0, 0] = 1;
        var uLo = new doubleN(1, Allocator.Temp, true); uLo[0] = (double)(-1);
        var uHi = new doubleN(1, Allocator.Temp, true); uHi[0] = (double)1;

        Assert.Catch<ArgumentException>(() => new doubleMPCState(2, 1, 4, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi));

        A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
    }

    [Test]
    public void DisposeIsIdempotent()
    {
        var A = new doubleMxN(2, 2, Allocator.Temp); A[0, 0] = 1; A[0, 1] = 1; A[1, 1] = 1;
        var B = new doubleMxN(2, 1, Allocator.Temp); B[1, 0] = 1;
        var Q = new doubleMxN(2, 2, Allocator.Temp); Q[0, 0] = 1; Q[1, 1] = 1;
        var R = new doubleMxN(1, 1, Allocator.Temp); R[0, 0] = 1;
        var uLo = new doubleN(1, Allocator.Temp, true); uLo[0] = (double)(-1);
        var uHi = new doubleN(1, Allocator.Temp, true); uHi[0] = (double)1;
        var mpc = new doubleMPCState(2, 1, 4, Allocator.Temp, in A, in B, in Q, in R, in uLo, in uHi);

        Assert.IsTrue(mpc.IsCreated);
        mpc.Dispose();
        Assert.DoesNotThrow(() => mpc.Dispose());

        A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); uLo.Dispose(); uHi.Dispose();
    }
}
